use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl MetaItemLit { # [doc = " Converts a token literal into a meta item literal."] pub fn from_token_lit (token_lit : token :: Lit , span : Span) -> Result < MetaItemLit , LitError > { Ok (MetaItemLit { symbol : token_lit . symbol , suffix : token_lit . suffix , kind : LitKind :: from_token_lit (token_lit) ? , span , }) } # [doc = " Cheaply converts a meta item literal into a token literal."] pub fn as_token_lit (& self) -> token :: Lit { let kind = match self . kind { LitKind :: Bool (_) => token :: Bool , LitKind :: Str (_ , ast :: StrStyle :: Cooked) => token :: Str , LitKind :: Str (_ , ast :: StrStyle :: Raw (n)) => token :: StrRaw (n) , LitKind :: ByteStr (_ , ast :: StrStyle :: Cooked) => token :: ByteStr , LitKind :: ByteStr (_ , ast :: StrStyle :: Raw (n)) => token :: ByteStrRaw (n) , LitKind :: CStr (_ , ast :: StrStyle :: Cooked) => token :: CStr , LitKind :: CStr (_ , ast :: StrStyle :: Raw (n)) => token :: CStrRaw (n) , LitKind :: Byte (_) => token :: Byte , LitKind :: Char (_) => token :: Char , LitKind :: Int (..) => token :: Integer , LitKind :: Float (..) => token :: Float , LitKind :: Err (guar) => token :: Err (guar) , } ; token :: Lit :: new (kind , self . symbol , self . suffix) } # [doc = " Converts an arbitrary token into meta item literal."] pub fn from_token (token : & Token) -> Option < MetaItemLit > { token :: Lit :: from_token (token) . and_then (| token_lit | MetaItemLit :: from_token_lit (token_lit , token . span) . ok ()) } }